#include "Power.h"
#include <fstream>
#include <iostream>
#include <stdexcept>
using namespace aftertaste;using K=MachineKind;using E=EnergyMedium;
static int checks=0;
static void require(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}
static Factory bench(){Factory f;f.machines.clear();f.energyLinks.clear();f.blueprints.clear();f.water=10000;f.electricity=10000;require(f.stamp(Factory::nuclearLabBlueprint(),{0,0}),"stamp lab module");f.at({2,0})->power.store[size_t(E::DC)]=300;for(Position p:{Position{1,1},Position{1,2}}){f.at(p)->power.lab.fuel=100;f.at(p)->power.lab.armed=true;}return f;}
static void advance(Factory& f,int n){for(int i=0;i<n;i++){++f.tick;f.beginPowerStep();f.finishPowerStep();}}
int main(int argc,char** argv){try{
 auto plan=Factory::nuclearLabBlueprint();for(const auto& n:plan.links)require(n.at.x>=0&&n.at.y>=0&&n.at.x<plan.width&&n.at.y<plan.height&&validPowerLink(n.link),"module conduits stay in bounds");
 for(E e:{E::Vacuum,E::Instrument})require(isEnergyConduit(energyConduit(e))&&conduitMedium(energyConduit(e))==e&&!isEnergyMachine(energyConduit(e)),"new conduit media round trip without changing old enum IDs");
 {auto f=bench();advance(f,48);auto& pile=*f.at({1,1});auto& star=*f.at({1,2});auto& cal=*f.at({2,1});auto& scope=*f.at({1,0});std::cout<<"Bench: pile heat "<<pile.power.lab.heatTotal<<", star heat "<<star.power.lab.heatTotal<<", DC "<<cal.power.lab.dcTotal<<", vacuum "<<star.power.lab.vacuum<<", temperature "<<pile.power.temperature<<"\n";
 require(pile.power.lab.heatTotal>500&&star.power.lab.heatTotal>100,"both experimental chambers produce actual heat");require(star.power.lab.vacuum>.9&&star.power.lab.inputTotal>50,"star chamber evacuates and spends real excitation energy");require(cal.power.lab.dcTotal>100&&cal.power.lab.dcTotal<cal.power.lab.heatTotal,"calorimeter converts actual finite heat with losses");require(scope.power.lab.trials.size()==2&&scope.power.lab.trials.back().draw>0&&scope.power.lab.trials.back().dc>0&&!scope.power.lab.trials.back().settings.empty(),"recorder captures measured 24-tick comparisons");require(std::abs(100-pile.power.lab.fuel-pile.power.lab.spent)<1e-7,"cartridge charge conserved as spent specimen");require(std::abs(f.powerContactFlow({0,2},{1,2},E::Vacuum))>0&&std::abs(f.powerContactFlow({1,1},{2,1},E::Heat))>0,"vacuum and heat actually cross touching apparatus");
 double flux=pile.power.lab.flux;f.configure({1,1},"lab-arm");advance(f,2);require(!pile.power.lab.armed&&pile.power.lab.flux<flux,"scram stops excitation and residual flux decays");require(!f.configure({1,2},"lab-load"),"armed hot chamber cannot load fuel");
 require(f.captureBlueprint({0,0},{5,2},"measured lab"),"capture complete experiment");require(f.stamp(f.blueprints.back(),{30,0}),"reuse connected experiment");auto& copied=*f.at({31,1});require(copied.power.lab.fuel==0&&copied.power.lab.heatTotal==0&&!copied.power.lab.armed&&copied.power.lab.tuning==pile.power.lab.tuning,"plans retain tuning without cloning cartridge, observations or live energy");}
 {auto good=bench(),bad=bench();bad.at({1,2})->power.lab.tuning=0;advance(good,60);advance(bad,60);require(good.at({1,2})->power.lab.heatTotal>bad.at({1,2})->power.lab.heatTotal*2,"resonance experiment has a measurable yield consequence");}
 {auto f=bench();f.at({1,1})->power.lab.armed=false;f.at({1,2})->power.lab.tuning=0;advance(f,48);const auto& trial=f.at({1,0})->power.lab.trials.back();require(trial.dc<trial.draw,"badly tuned star experiment visibly has negative electrical return");}
 {auto f=bench();advance(f,18);f.at({0,2})->enabled=false;advance(f,12);require(f.at({1,2})->power.lab.vacuum==0,"disconnecting pump loses chamber vacuum");double before=f.at({1,2})->power.lab.heatTotal;advance(f,12);require(f.at({1,2})->power.lab.heatTotal==before,"no vacuum means no nuclear pulse");}
 {auto f=bench();advance(f,12);f.at({1,0})->enabled=false;advance(f,1);require(!f.at({1,1})->power.lab.armed,"isolating the contact recorder opens chamber interlock");}
 {auto f=bench();advance(f,12);f.at({3,1})->enabled=false;f.at({1,1})->power.temperature=104;advance(f,4);require(f.at({1,1})->power.tripped&&!f.at({1,1})->power.lab.armed,"loss of cooling overheats and latches scram");require(!f.configure({1,1},"power-reset"),"hot bench cannot bypass reset interlock");}
 {auto f=bench();auto& pile=*f.at({1,1});pile.power.lab.fuel=.01;advance(f,24);require(pile.power.lab.fuel<1e-7&&!pile.power.lab.armed&&pile.power.lab.heatTotal<=4.00001,"finite cartridge cannot create unlimited energy");pile.power.lab.flux=0;pile.power.temperature=20;f.chemicals=.4;require(f.configure({1,1},"lab-load")&&f.chemicals<1e-8&&pile.power.lab.fuel==40,"replacement cartridge debits actual chemical input");}
 {auto f=bench();advance(f,48);auto file=std::filesystem::temp_directory_path()/"aftertaste-nuclear-test.json";f.storageFile=file;require(f.save(),"save running experiment");Factory loaded;loaded.storageFile=file;require(loaded.load()&&json(static_cast<FactoryState&>(loaded))==json(static_cast<FactoryState&>(f)),"fuel, interlocks, vacuum, counters and experiment logs persist exactly");auto j=json{{"version",13},{"factory",static_cast<FactoryState&>(f)}};j["factory"]["machines"][0]["machine"]["power"]["lab"]["fuel"]=-1;{std::ofstream out(file);out<<j;}require(!loaded.load(),"invalid experimental inventory is rejected atomically");std::filesystem::remove(file);}
 {Factory f;require(std::any_of(f.machines.begin(),f.machines.end(),[](const auto& m){return m.second.kind==K::CuriosityPile;}),"fresh demo includes connected nuclear laboratory");f.water=100000;f.farmProduce=10000;f.chemicals=100;for(int tick=0;tick<120;tick++)f.step();double nuclear=0;for(const auto& [p,m]:f.machines)if(m.kind==K::Calorimeter)nuclear+=m.power.lab.dcTotal;std::cout<<"Demo nuclear DC "<<nuclear<<"\n";require(nuclear>1500,"demo nuclear lab supplies substantial measured electrical output");}
 if(argc>1){std::ifstream input(argv[1]);json j;input>>j;auto old=j.at("factory").get<FactoryState>();Factory f;f.storageFile=argv[1];require(f.load(),"migrate supplied version-11 factory");for(const auto& [p,m]:old.machines)require(f.at(p)&&json(*f.at(p))==json(m),"existing machine and food state retained exactly");require(f.tick==old.tick&&f.water==old.water&&f.chemicals==old.chemicals&&f.stock==old.stock,"migration leaves clock, water, chemicals and pantry intact");auto file=std::filesystem::temp_directory_path()/"aftertaste-nuclear-migration.json";f.storageFile=file;require(f.save(),"save upgraded factory");Factory again;again.storageFile=file;require(again.load()&&json(static_cast<FactoryState&>(again))==json(static_cast<FactoryState&>(f)),"reload cannot duplicate laboratory or starter cartridges");std::filesystem::remove(file);
  old.machines[{nuclearLabOrigin.x,nuclearLabOrigin.y}]=Machine{};auto before=json(old);require(!installNuclearLabIn(old)&&json(old)==before,"custom construction blocks annex without overwriting player work");}
 std::cout<<"PASS nuclear laboratory: "<<checks<<" checks\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL nuclear laboratory: "<<e.what()<<" (check "<<checks<<")\n";return 1;}}
